  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Rappottenstein', 'Jeden z nejzachovalejších středověkých hradů Rakouska nebyl nikdy dobyt a dodnes patří rodu Abensperg-Traun. Mohutná románsko-gotická pevnost na žulovém ostrohu nad říčkou Kamp nabízí komentované prohlídky i výhled na lesy Waldviertelu. Příjezdová silnička od Zwettlu je samá zatáčka mezi balvany.', 48.5236, 15.0808, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rappottenstein%20-%20Burg.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rappottenstein%20-%20Burg.JPG"}'::text[], 0),
    (v_route, 'Klášter Zwettl', 'Cisterciácký klášter z roku 1138 patří k nejstarším v Rakousku a dodnes v něm žije řádová komunita. Za prohlídku stojí gotický křížový chodba, barokní věž kostela a klášterní zahrady u řeky Kamp. Ideální krátká zastávka hned na začátku okruhu.', 48.6167, 15.2039, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Zwettl.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Zwettl.jpg"}'::text[], 1),
    (v_route, 'Přehrada Ottenstein', 'Přehradní jezero na Kampu s členitými zátokami, žulovými ostrůvky a vodou vhodnou ke koupání. Nad hladinou trůní zřícenina Lichtenfels, kterou je z hráze krásně vidět. Silnice kolem nádrže se vlní nad vodou a patří k jízdním vrcholům trasy.', 48.6072, 15.3236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stausee%20Ottenstein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stausee%20Ottenstein.jpg"}'::text[], 2),
    (v_route, 'Zámek Rosenburg', 'Renesanční zámek nad údolím Kampu je proslulý dochovaným turnajovým nádvořím a ukázkami sokolnictví — dravci tu létají divákům přímo nad hlavami. Interiéry ukrývají zbrojnici a bohaté sbírky. Z parkoviště je pěkný výhled do kaňonu řeky.', 48.6319, 15.6392, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Rosenburg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Rosenburg.jpg"}'::text[], 3),
    (v_route, 'Zřícenina Gars am Kamp', 'Nad městečkem Gars se zvedá rozlehlá zřícenina babenberského hradu z 11. století, jednoho z nejstarších panovnických sídel Rakouska. Volně přístupný areál nabízí výhled na údolí Kampu a vinice. Dole ve městě je příjemná náves na kávu.', 48.5942, 15.6564, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gars%20am%20Kamp%20-%20Burgruine.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gars%20am%20Kamp%20-%20Burgruine.JPG"}'::text[], 4),
    (v_route, 'Restaurace: Bräuhaus Zwettl (Zwettl)', 'Restaurace zwettlského rodinného pivovaru, který vaří pivo už od roku 1708. Poctivá rakouská kuchyně — Zwiebelrostbraten, řízek i sezónní speciality — a čepované Zwettler přímo od zdroje. Ideální zakončení okruhu na náměstí ve Zwettlu.', 48.6039, 15.1683, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zwettl%20-%20Hauptplatz.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zwettl%20-%20Hauptplatz.JPG"}'::text[], 5);
