  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Freistadt — historické centrum', 'Dokonale zachované středověké město s kompletními hradbami, dvěma branami a podloubím kolem náměstí. Freistadt je zároveň pivovarské město — místní Braucommune vlastní měšťané už od roku 1777. Skvělý výchozí bod okruhu s parkováním hned za hradbami.', 48.5114, 14.5047, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freistadt%20Hauptplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freistadt%20Hauptplatz.jpg"}'::text[], 0),
    (v_route, 'Kefermarkt — gotický oltář', 'V nenápadném kostele sv. Wolfganga stojí jeden z největších pokladů střední Evropy — třináct metrů vysoký pozdně gotický křídlový oltář vyřezaný z lipového dřeva kolem roku 1497. Jemnost řezby bere dech i lidem, kteří do kostelů běžně nechodí. Zastávka na dvacet minut, které stojí za to.', 48.4433, 14.5386, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kefermarkt%20Fl%C3%BCgelaltar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kefermarkt%20Fl%C3%BCgelaltar.jpg"}'::text[], 1),
    (v_route, 'Bad Leonfelden', 'Lázeňské městečko na staré solné stezce z Lince do Čech, známé perníkářskou tradicí rodiny Kastner (pekárna funguje od roku 1559). Podél malebného náměstí se dá koupit perník na cestu. Odsud se silnice stáčí na západ do nejhezčí, zvlněné části Mühlviertelu.', 48.5253, 14.2942, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Leonfelden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Leonfelden.jpg"}'::text[], 2),
    (v_route, 'Klášter Schlägl', 'Premonstrátský klášter z 13. století pod šumavským hřebenem, jediný klášterní pivovar Horního Rakouska. Barokní kostel, obrazárna a klášterní pivnice s výborným tmavým ležákem. Okolní silničky pod Hochfichtem se jezdí skvěle a je odtud vidět na českou stranu Šumavy.', 48.6394, 13.9625, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Schl%C3%A4gl.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Schl%C3%A4gl.jpg"}'::text[], 3),
    (v_route, 'Schlögener Schlinge — vyhlídka', 'Nejslavnější říční meandr Rakouska: Dunaj se u Schlögenu otočí o 180 stupňů mezi strmými zalesněnými srázy. Z vyhlídky Schlögener Blick nad pravým břehem je celá smyčka jako na dlani — k plošině se jde od parkoviště asi 20 minut pěšky. Jedno z nejfotografovanějších míst Horního Rakouska.', 48.4494, 13.9439, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schl%C3%B6gener%20Schlinge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schl%C3%B6gener%20Schlinge.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Freistädter Brauhaus (Freistadt)', 'Restaurace městského pivovaru Freistädter Bier, kde se vaří už přes dvě stě let. Vydatná hornorakouská kuchyně a pivní speciály z tanků pár metrů od výčepu. Perfektní tečka za okruhem po návratu do Freistadtu.', 48.5108, 14.5031, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freistadt.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freistadt.jpg"}'::text[], 5);
