  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bregenz a Pfänder', 'Hlavní město Vorarlberska leží přímo na břehu Bodamského jezera, proslulé je operní scénou na vodě. Nad městem se zvedá Pfänder (1064 m) — lanovkou nebo silničkou se dá vyjet k vyhlídce, ze které je vidět jezero, Rýnská delta a prý až 240 alpských vrcholů. Skvělý start dne.', 47.5031, 9.7471, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bregenz%20vom%20Pf%C3%A4nder.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bregenz%20vom%20Pf%C3%A4nder.jpg"}'::text[], 0),
    (v_route, 'Bezau', 'Srdce Bregenzerwaldu a ukázka místní dřevěné architektury — šindelové fasády tu mají i moderní domy. Vesnice je centrem sýrařské stezky KäseStrasse, takže ochutnávka horského sýra je povinnost. Odsud začíná nejhezčí horská část trasy.', 47.3856, 9.9003, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bezau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bezau.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Gasthof Gams (Bezau)', 'Tradiční hostinec v centru Bezau vaří moderní vorarlberskou kuchyni z regionálních surovin — sýrové Kässpätzle jsou tu zážitek. Příjemná zahrada a rychlá obsluha i pro motorkáře v kombinéze. Dobré místo na oběd před stoupáním do hor.', 47.3861, 9.8994, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bezau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bezau.jpg"}'::text[], 2),
    (v_route, 'Kanisfluh — vyhlídka', 'Mohutný vápencový masiv Kanisfluh (2044 m) je symbolem Bregenzerwaldu — z údolí mezi Mellau a Au působí jako obří kamenná vlna nad loukami. U silnice je několik míst na fotku. Jeden z nejfotogeničtějších úseků celé trasy.', 47.3236, 9.9364, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanisfluh.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kanisfluh.jpg"}'::text[], 3),
    (v_route, 'Damüls', 'Nejvýše položená vesnice Bregenzerwaldu (1428 m) drží evropský rekord v průměrném úhrnu sněhu, v létě je to ale rozkvetlá horská terasa s výhledem na Damülser Mittagspitze. Stoupání z Au nabízí sérii pěkných serpentin. Krátká odbočka, která stojí za to.', 47.2806, 9.8919, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dam%C3%BCls.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dam%C3%BCls.jpg"}'::text[], 4),
    (v_route, 'Hochtannbergpass', 'Průsmyk ve výšce 1676 metrů spojuje Bregenzerwald s údolím Lechu. Nad sedlem se tyčí zubatý Widderstein a kousek pod vrcholem leží idylické jezírko Körbersee, přístupné pěšky. Otevřená horská krajina nad hranicí lesa s výhledy na všechny strany.', 47.2589, 10.0089, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hochtannbergpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hochtannbergpass.jpg"}'::text[], 5),
    (v_route, 'Lech am Arlberg', 'Světoznámá horská vesnice na mladé řece Lech, v zimě hřiště královských rodin, v létě překvapivě klidné místo s trávou porostlými sjezdovkami. Cíl trasy s řadou kaváren a teras u řeky. Kdo chce pokračovat, může sjet do Warthu a dál Lechtalem.', 47.2081, 10.1419, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lech%20am%20Arlberg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lech%20am%20Arlberg.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Landeck', 'Středověký zámek na skále nad soutokem Innu a Sanny střeží křižovatku cest mezi Arlbergem, Reschenpassem a Fernpassem. Dnes v něm sídlí muzeum regionu a galerie, z věže je výhled na celé město. Dobré místo na kávu před odbočením do Kaunertalu.', 47.1392, 10.5647, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Landeck.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Landeck.jpg"}'::text[], 0),
    (v_route, 'Prutz', 'Vesnice v širokém údolí horního Innu, kde začíná odbočka do Kaunertalu i serpentiny na vyhlídku Gachen Blick nad Naturparkem Kaunergrat. Poslední pohodlné tankování před ledovcovou silnicí. Kolem obce rostou nejvýše položené vinice Tyrolska.', 47.0794, 10.6647, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prutz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prutz.jpg"}'::text[], 1),
    (v_route, 'Kaunertal — Feichten', 'Hlavní vesnice úzkého ledovcového údolí a vstupní brána mýtné Gletscherstraße. Tradiční tyrolské statky, kostelík a informační centrum Naturparku Kaunergrat. Odsud začíná souvislé stoupání — 29 serpentin a přes 1500 výškových metrů.', 47.0072, 10.7181, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaunertal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaunertal.jpg"}'::text[], 2),
    (v_route, 'Gepatsch-Stausee', 'Šest kilometrů dlouhá přehrada s tyrkysovou ledovcovou vodou, sevřená třítisícovkami Kaunergratu. Silnice se vine přímo nad hladinou a nabízí jedny z nejkrásnějších kilometrů celé trasy. U hráze je vyhlídkové parkoviště.', 46.9631, 10.7392, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gepatschspeicher.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gepatschspeicher.jpg"}'::text[], 3),
    (v_route, 'Kaunertaler Gletscher', 'Konec silnice ve výšce 2750 metrů, pár kroků od splazu ledovce Weißseeferner. I v červenci tu leží sníh a panorama Ötztalských Alp je na dosah ruky. Jedno z mála míst v Alpách, kam se dá k ledovci dojet po asfaltu — zážitek, který se neokouká.', 46.8703, 10.7108, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaunertaler%20Gletscher.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaunertaler%20Gletscher.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Gletscherrestaurant Weißsee (Kaunertal)', 'Samoobslužná horská restaurace přímo na konci ledovcové silnice ve 2750 metrech. Polévky, tyrolská klasika a horký čaj s výhledem na ledovec z prosklené terasy. Nejvýše položený oběd, jaký si v Rakousku na motorce dopřejete.', 46.8710, 10.7115, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaunertaler%20Gletscherstra%C3%9Fe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaunertaler%20Gletscherstra%C3%9Fe.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klášter Admont — knihovna', 'Benediktinský klášter Admont ukrývá největší klášterní knihovní sál světa — 70 metrů bílé a zlaté barokní nádhery se 70 000 svazky a freskami. Vedle knihovny stojí za vidění přírodovědné muzeum. Otvírá v deset, naplánujte si start podle toho.', 47.5758, 14.4611, 'https://commons.wikimedia.org/wiki/Special:FilePath/Austria%20-%20Admont%20Abbey%20Library%20-%201407.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Austria%20-%20Admont%20Abbey%20Library%20-%201407.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stift%20Admont.jpg"}'::text[], 0),
    (v_route, 'NP Gesäuse — Gesäuseeingang', 'Vstup do soutěsky, kde se Enns zařezává mezi kolmé stěny Hochtoru a Buchsteinu — název Gesäuse znamená "hučení". Národní park je rájem vodáků a horolezců, silnice B146 jím vede přímo podél řeky. Vyhlídkové zálivy zvou k zastávce na fotku.', 47.5875, 14.5378, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ges%C3%A4useeingang.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ges%C3%A4useeingang.jpg"}'::text[], 1),
    (v_route, 'Leopoldsteiner See', 'Smaragdové jezero pod kolmou stěnou Seemauer, jedno z nejchladnějších a nejčistších v Rakousku. Od parkoviště je to k břehu pár minut pěšky a scenérie připomíná spíš Norsko než Štýrsko. Ideální krátká pauza před Eisenerzem.', 47.5647, 14.8681, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leopoldsteiner%20See.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Leopoldsteiner%20See.jpg"}'::text[], 2),
    (v_route, 'Erzberg — rudná hora', 'Největší povrchový důl na železnou rudu ve střední Evropě — rezavě rudá pyramida s terasami, na kterých se každoročně jezdí extrémní enduro Erzbergrodeo. Vyhlídka od silnice ukazuje celé "štýrské schodiště", v sezóně jezdí po dole vyhlídkový obří truck Hauly. Pro motorkáře skoro poutní místo.', 47.5333, 14.8931, 'https://commons.wikimedia.org/wiki/Special:FilePath/Steirischer%20Erzberg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Steirischer%20Erzberg.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Erzbergbräu (Eisenerz)', 'Minipivovar s restaurací v historickém centru hornického Eisenerzu. Nefiltrované pivo vařené z místní horské vody a poctivá štýrská kuchyně — vydatný oběd před stoupáním do Präbichlu. Středověké uličky města stojí za krátkou procházku.', 47.5406, 14.8853, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eisenerz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eisenerz.jpg"}'::text[], 4),
    (v_route, 'Präbichl', 'Horské sedlo (1226 m) nad Eisenerzem s výhledem zpět na Erzberg a na vápencové stěny Hochschwabského masivu. Stoupání od Eisenerzu je série širokých, rychlých serpentin. Z sedla lze sjet do Vordernbergu a pokračovat údolím Muru, nebo se vrátit soutěskou zpět.', 47.5158, 14.9481, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pr%C3%A4bichl.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pr%C3%A4bichl.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Leibnitz', 'Pohodové okresní město mezi řekami Mur a Sulm, přirozené centrum jihoštýrského vinařství. Náměstí s kavárnami je ideální na ranní kávu před okruhem. Všude kolem se zvedají první vinorodé kopce.', 46.7811, 15.5450, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leibnitz%20Hauptplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Leibnitz%20Hauptplatz.jpg"}'::text[], 0),
    (v_route, 'Zámek Seggau', 'Bývalá rezidence štýrských biskupů na kopci nad Leibnitzem, s renesančními arkádami a jednou z nejstarších vinoték Rakouska ve sklepích ze 17. století. Z nádvoří je výhled na celé údolí Sulmu. Krátká zastávka hned na začátku trasy.', 46.7717, 15.5236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Seggau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Seggau.jpg"}'::text[], 1),
    (v_route, 'Kitzeck im Sausal', 'Nejvýše položená vinařská obec Rakouska (564 m) trůní na hřebeni Sausalu mezi strmými vinicemi. Cesta nahoru je řetěz serpentin mezi réví a výhled sahá od Koralpe po slovinské hory. V obci je malé vinařské muzeum a řada vináren s terasami.', 46.7789, 15.4592, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kitzeck%20im%20Sausal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kitzeck%20im%20Sausal.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Sattlerhof (Gamlitz)', 'Rodinný vinařský hotel s vyhlášenou restaurací nad Gamlitzem — moderní štýrská kuchyně ze surovin od okolních farmářů, degustační sklo Sauvignonu pro spolujezdce. Rezervace se o víkendech vyplatí. Jedna z nejlepších kuchyní jižního Štýrska.', 46.6858, 15.5433, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gamlitz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gamlitz.jpg"}'::text[], 3),
    (v_route, 'Jihoštýrská vinná stezka — Ratsch', 'Nejslavnější úsek vinné stezky se vlní po hřebeni přímo nad slovinskou hranicí — vinice padají do údolí na obě strany a mezi řadami réví klapou dřevěné větrné plašiče klapotetz. Každých pár set metrů je vyhlídka nebo buschenschank. Silničářský i fotografický vrchol okruhu.', 46.6486, 15.5364, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%BCdsteirische%20Weinstra%C3%9Fe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%BCdsteirische%20Weinstra%C3%9Fe.jpg"}'::text[], 4),
    (v_route, 'Mauzoleum Ehrenhausen', 'Nad městečkem Ehrenhausen stojí manýristické mauzoleum vojevůdce Ruprechta von Eggenberg z počátku 17. století — bílá stavba s kopulí viditelná z celého údolí Muru. Ke stavbě se stoupá alejí od náměstí. Poslední kulturní zastávka před návratem do Leibnitzu.', 46.7231, 15.5906, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mausoleum%20Ehrenhausen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mausoleum%20Ehrenhausen.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Villach', 'Živé město na Drávě s italsky uvolněnou atmosférou — do Itálie i Slovinska je to odsud pár desítek kilometrů. Hlavní náměstí s kostelem sv. Jakuba je plné kaváren. Praktický start okruhu s dobrým zázemím.', 46.6111, 13.8558, 'https://commons.wikimedia.org/wiki/Special:FilePath/Villach%20Hauptplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Villach%20Hauptplatz.jpg"}'::text[], 0),
    (v_route, 'Villacher Alpenstraße — Dobratsch', 'Šestnáct kilometrů mýtné panoramatické silnice končí na Rosstratte v 1732 metrech pod vrcholem Dobratsche. Cestou je řada vyhlídek na Julské Alpy, Karavanky a obří skalní zřícení z roku 1348. Dobratsch je dnes přírodní park, nahoře se dá dojít k vysílači s kruhovým rozhledem.', 46.6019, 13.6772, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dobratsch.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dobratsch.jpg"}'::text[], 1),
    (v_route, 'Faaker See', 'Tyrkysové jezero pod horou Mittagskogel, jehož barvu nezachytí žádná fotka věrně. Kolem břehů vedou stinné silničky a je tu spousta pláží na rychlé osvěžení. Motorkářům je kraj důvěrně známý — u jezera se každoročně koná obří sraz European Bike Week.', 46.5794, 13.9236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Faaker%20See.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Faaker%20See.jpg"}'::text[], 2),
    (v_route, 'Velden am Wörthersee', 'Mondénní letovisko na západním břehu Wörthersee se žlutým zámkem známým z televizní obrazovky a promenádou plnou života. Jezero je nejteplejší velké alpské jezero, v létě má i 26 stupňů. Ideální na zmrzlinu a korzo podél mol.', 46.6122, 14.0386, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Velden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Velden.jpg"}'::text[], 3),
    (v_route, 'Pyramidenkogel', 'Nejvyšší dřevěná rozhledna světa (100 m) na kopci nad jižním břehem Wörthersee. Elipsovitá věž z lepených modřínových sloupů nabízí kruhový výhled na jezera, Karavanky a Alpy — dolů se dá sjet krytou skluzavkou. Výjezd na kopec je pěkná serpentinová tečka.', 46.6103, 14.1439, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pyramidenkogel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pyramidenkogel.jpg"}'::text[], 4),
    (v_route, 'Burg Landskron', 'Hrad na skále mezi Villachem a Ossiacher See, proslulý letovými ukázkami dravců Adlerarena — orli a supi tu plachtí nad hlavami diváků s kulisou jezera. Příjezdová cesta serpentinami je krátká, ale šťavnatá. Z teras je jeden z nejhezčích výhledů Korutan.', 46.6417, 13.8969, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Landskron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Landskron.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Burgrestaurant Landskron (Villach)', 'Restaurace přímo v areálu hradu Landskron s terasou nad Ossiacher See. Korutanské speciality jako Kasnudeln a čerstvé ryby z jezera, západ slunce nad hladinou jako bonus. Důstojné zakončení okruhu pár kilometrů před Villachem.', 46.6420, 13.8975, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ossiacher%20See.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ossiacher%20See.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pevnost Kufstein', 'Mohutná pevnost na skále nad Innem střeží tyrolsko-bavorskou hranici už od 13. století. Uvnitř je muzeum a Heldenorgel — největší venkovní varhany světa, které hrají každý den v poledne a jsou slyšet po celém městě. Nahoru vede šikmý výtah z centra.', 47.5847, 12.1706, 'https://commons.wikimedia.org/wiki/Special:FilePath/Festung%20Kufstein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Festung%20Kufstein.jpg"}'::text[], 0),
    (v_route, 'Walchsee', 'Teplé rekreační jezero pod severními stěnami Zahmer Kaiser s plážemi a promenádou. Voda má v létě přes 23 stupňů, takže rychlá koupel do okruhu klidně patří. Silnice kolem jezera směrem na Kössen je příjemně zvlněná.', 47.6511, 12.3194, 'https://commons.wikimedia.org/wiki/Special:FilePath/Walchsee.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Walchsee.jpg"}'::text[], 1),
    (v_route, 'St. Johann in Tirol', 'Městečko s malovanými barokními fasádami na křižovatce údolí mezi Wilder Kaiser a Kitzbühelskými Alpami. Náměstí s kostelem Nanebevzetí Panny Marie je jako z pohlednice. Dobrá zastávka na kávu v půlce dopolední etapy.', 47.5236, 12.4278, 'https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Johann%20in%20Tirol.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Johann%20in%20Tirol.jpg"}'::text[], 2),
    (v_route, 'Kitzbühel — Vorderstadt', 'Legendární zimní metropole s barevnou středověkou Vorderstadt, kde se v lednu chodí slavit vítězství ze sjezdovky Streif na Hahnenkammu. V létě je město příjemně klidné a butiky střídají terasy kaváren. Gondolou se dá vyjet k výhledům na Kaisergebirge.', 47.4464, 12.3922, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kitzb%C3%BChel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kitzb%C3%BChel.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Huberbräu Stüberl (Kitzbühel)', 'Nefalšovaná tyrolská hospoda přímo ve Vorderstadt — řízek přes talíř, gulášová polévka a čepovaný Huberbräu za ceny, které v Kitzbühelu nečekáte. Mezi místními i lyžařskými legendami jde o instituci. V poledne bývá plno, ale fronta odsýpá.', 47.4468, 12.3917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kitzb%C3%BChel%20Vorderstadt.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kitzb%C3%BChel%20Vorderstadt.jpg"}'::text[], 4),
    (v_route, 'Pass Thurn', 'Sedlo v 1274 metrech na hranici Tyrolska a Salcburska, odkud se poprvé otevře panorama zasněžených Vysokých Taur. Stoupání od Jochbergu je plynulé a rychlé, nahoře je parkoviště s výhledem. Obratiště okruhu — zpět se sjíždí stejným směrem s výhledem na Kaisergebirge.', 47.3006, 12.4200, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pass%20Thurn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pass%20Thurn.jpg"}'::text[], 5),
    (v_route, 'Ellmau — Wilder Kaiser', 'Vesnice pod jižními stěnami Wilder Kaiser, proslulá seriálem Doktor z hor. Z luk nad obcí je nejslavnější pohled na celý masiv — kolmé vápencové věže nad zelenými pastvinami. Zpáteční silnice přes Söll a Scheffau je scénická tečka okruhu.', 47.5150, 12.3006, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wilder%20Kaiser.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wilder%20Kaiser.jpg"}'::text[], 6);
