  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Waidhofen an der Ybbs', 'Středověké město železářů s věžemi, zamračenými měšťanskými domy a moderně zrekonstruovaným zámkem Rothschildů. Historické centrum nad řekou Ybbs patří k nejhezčím v Dolním Rakousku. Ideální start s kávou na náměstí Oberer Stadtplatz.', 47.9603, 14.7717, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waidhofen%20an%20der%20Ybbs.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Waidhofen%20an%20der%20Ybbs.jpg"}'::text[], 0),
    (v_route, 'Ybbsitz', 'Vesnice na železné stezce Eisenstraße, po staletí centrum kovářského řemesla — dodnes tu fungují historické hamry a muzeum kování FeRRUM. Každé dva roky se koná mezinárodní setkání kovářů. Krátká zastávka s vůní uhlí a železa.', 47.9469, 14.8925, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ybbsitz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ybbsitz.jpg"}'::text[], 1),
    (v_route, 'Lunzer See', 'Jediné přírodní jezero Dolního Rakouska leží v tichém kotli pod Dürrensteinem. Křišťálová voda, dřevěné lázně z roku 1928 a plovoucí jeviště letního festivalu — atmosféra jak z první republiky. Osvěžující koupel v půlce trasy přijde vhod.', 47.8531, 15.0475, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lunzer%20See.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lunzer%20See.jpg"}'::text[], 2),
    (v_route, 'Ötscher — Lackenhof', 'Horská vesnička na úpatí Ötscheru, osamělého vápencového kužele, kterému se říká strážce Mostviertelu. Sedačkovou lanovkou se dá vyvézt pod vrchol; výhled sahá od Dunaje po Hochschwab. Silnička ze sedla Grubberg do Lackenhofu je řetěz lesních zatáček.', 47.8631, 15.1417, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%96tscher.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%96tscher.jpg"}'::text[], 3),
    (v_route, 'Kartouza Gaming', 'Největší kartuziánský klášter střední Evropy, založený roku 1330 habsburským vévodou Albrechtem II., dnes ožívá hotelem, muzeem a letním hudebním festivalem. Gotický kostel a rozlehlé nádvoří stojí za procházku. V klášterní restauraci Kartausenkeller vaří poctivou rakouskou klasiku — dobrá pozdní zastávka na jídlo.', 47.9294, 15.0894, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kartause%20Gaming.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kartause%20Gaming.jpg"}'::text[], 4);
  insert into public.routes
