  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lienz', 'Slunečné hlavní město Východního Tyrolska pod stěnami Lienzských Dolomit, s jižansky živým náměstím a zámkem Bruck nad městem. Poslední větší město s plným zázemím před odlehlým Lesachtalem — doplňte palivo. Kavárny na Hauptplatzu mají italské espresso.', 46.8289, 12.7692, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lienz%20Hauptplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lienz%20Hauptplatz.jpg"}'::text[], 0),
    (v_route, 'Kartitsch a Kartitscher Sattel', 'Přes sedlo u Kartitsche (1525 m) se z Pustertalu vjíždí do zapadlého Tiroler Gailtalu. Vesnice je první zastávkou rakouské "vesnice pomalosti" — kraje, kde se čas měří jinak. Louky, seníky a panorama Karnských Alp přes údolí.', 46.7261, 12.5006, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kartitsch.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kartitsch.jpg"}'::text[], 1),
    (v_route, 'Obertilliach', 'Dokonale zachovaná horská vesnice s dřevěnými srubovými domy, kde se natáčely scény bondovky Spectre. Památkově chráněné centrum vypadá stejně jako před sto lety. Krátká procházka mezi statky voní dřevem a senem.', 46.7069, 12.6156, 'https://commons.wikimedia.org/wiki/Special:FilePath/Obertilliach.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Obertilliach.jpg"}'::text[], 2),
    (v_route, 'Maria Luggau — bazilika', 'Poutní bazilika Panny Marie Sněžné z 16. století s cibulovou věží je duchovním srdcem Lesachtalu — poutníci sem po staletí přicházejí pěšky i z Itálie. Vedle kláštera stojí obnovené vodní mlýny na strmé stráni. Nejfotogeničtější místo údolí.', 46.7169, 12.7369, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maria%20Luggau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Maria%20Luggau.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Landhaus Kellerwand (Kötschach-Mauthen)', 'Gurmánská instituce Korutan — rodina Sonnleitner tu desítky let vaří alpsko-adrijskou kuchyni, která posbírala řadu ocenění. Kdo nechce degustační menu, najde v bistru i lehčí polední klasiku. Rezervace doporučena, zážitek zaručen.', 46.6778, 13.0036, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6tschach-Mauthen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6tschach-Mauthen.jpg"}'::text[], 4),
    (v_route, 'Plöckenpass', 'Hraniční průsmyk (1357 m) mezi Korutany a italským Furlanskem, vybojovaný v horských bitvách první světové války — okolní vrcholy jsou protkané zákopy a muzejní stezkou. Stoupání z Mauthen je série ostrých serpentin s výhledy na Kellerwand. Cíl trasy; dolů do Itálie je to už jen z kopce.', 46.6019, 12.9439, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6ckenpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6ckenpass.jpg"}'::text[], 5);
